def combine_genes(self, gene_name, parent1_value, parent2_value, crossover_point, gene_index, total_genes):
    if gene_name == 'activation':
        # Cycle through activation functions to avoid premature convergence
        activations = ['ReLU', 'GELU', 'LeakyReLU', 'SiLU']
        idx1 = activations.index(parent1_value)
        idx2 = activations.index(parent2_value)
        if gene_index % 2 == 0:
            return activations[(idx1 + 1) % len(activations)]
        else:
            return activations[(idx2 + 1) % len(activations)]
    elif gene_name == 'pooling_type' or gene_name == 'conv_type' or gene_name == 'norm_type' or gene_name == 'optimizer_type':
        # Randomly choose between parents to promote diversity
        if random.random() < 0.5:
            return parent1_value
        else:
            return parent2_value
    elif gene_name == 'base_channels' or gene_name == 'lr':
        # Combine channels and learning rates using arithmetic mean
        return (parent1_value + parent2_value) / 2
