        # Average dropout probabilities but ensure they remain valid
        avg_dropout = (parent1_value + parent2_value) / 2
        return max(min(avg_dropout, 0.5), 0.05)
    elif gene_name == 'momentum':
        # Use geometric mean for momentum to balance exploration and exploitation
        return (parent1_value ** 0.5) * (parent2_value ** 0.5)
    elif gene_name == 'kernel_size':
        # Cycle through kernel sizes to avoid local minima
        kernels = [1, 3, 5, 7]
        idx1 = kernels.index(parent1_value)
        idx2 = kernels.index(parent2_value)
        if gene_index % 2 == 0:
            return kernels[(idx1 + 1) % len(kernels)]
        else:
            return kernels[(idx2 + 1) % len(kernels)]
    else:
        # Default to simple crossover for other parameters
